function first(...values) {
  return values.find((value) => value !== undefined && value !== null && String(value).trim() !== '');
}

function parseMaybeJson(value) {
  if (typeof value !== 'string') return value;
  try {
    return JSON.parse(value);
  } catch (error) {
    return value;
  }
}

function xmlTag(xml, tag) {
  if (typeof xml !== 'string') return undefined;
  const re = new RegExp(`<${tag}>(?:<!\\[CDATA\\[([\\s\\S]*?)\\]\\]>|([\\s\\S]*?))</${tag}>`, 'i');
  const match = xml.match(re);
  return match ? (match[1] ?? match[2]) : undefined;
}

function normalize(raw) {
  let body = raw.body ?? raw;
  body = parseMaybeJson(body);

  const isXml = typeof body === 'string' && body.trim().startsWith('<');
  const feishuContent = parseMaybeJson(body?.event?.message?.content ?? body?.message?.content);

  const platform = first(
    raw.query?.platform,
    body?.platform,
    isXml ? 'wechat' : undefined,
    body?.FromUserName ? 'wechat' : undefined,
    body?.update_id ? 'telegram' : undefined,
    body?.event ? 'feishu' : undefined,
    'wechat'
  );

  const rawType = first(
    body?.message_type,
    body?.type,
    body?.MsgType,
    body?.message?.voice ? 'voice' : undefined,
    body?.message?.text ? 'text' : undefined,
    isXml ? xmlTag(body, 'MsgType') : undefined,
    'text'
  );

  const text = first(
    body?.text,
    body?.content,
    body?.Content,
    body?.message?.text,
    body?.message?.text?.text,
    feishuContent?.text,
    body?.event?.message?.text,
    isXml ? xmlTag(body, 'Content') : undefined
  );

  const recognition = first(
    body?.recognition,
    body?.Recognition,
    body?.speech_text,
    body?.transcript,
    body?.asr_text,
    isXml ? xmlTag(body, 'Recognition') : undefined
  );

  const audioUrl = first(
    body?.audio_url,
    body?.voice_url,
    body?.media_url,
    body?.file_url,
    body?.audio?.url,
    body?.voice?.url,
    body?.message?.voice?.file_url
  );

  const mediaId = first(
    body?.media_id,
    body?.MediaId,
    isXml ? xmlTag(body, 'MediaId') : undefined,
    body?.message?.voice?.file_id
  );

  const senderId = first(
    body?.sender_id,
    body?.from_user,
    body?.FromUserName,
    isXml ? xmlTag(body, 'FromUserName') : undefined,
    body?.message?.from?.id,
    body?.event?.sender?.sender_id?.open_id,
    'unknown-sender'
  );

  const chatId = first(
    body?.chat_id,
    body?.conversation_id,
    body?.chat?.id,
    body?.message?.chat?.id,
    body?.event?.message?.chat_id,
    senderId
  );

  const messageId = first(
    body?.message_id,
    body?.MsgId,
    isXml ? xmlTag(body, 'MsgId') : undefined,
    body?.message?.message_id,
    body?.event?.message?.message_id,
    `${Date.now()}`
  );

  const inputText = first(text, recognition);
  const messageType = String(rawType).toLowerCase().includes('voice') || audioUrl || mediaId ? 'voice' : 'text';

  return {
    platform,
    message_type: messageType,
    sender_id: String(senderId),
    chat_id: String(chatId),
    message_id: String(messageId),
    input_text: inputText ? String(inputText).trim() : '',
    audio_url: audioUrl ? String(audioUrl).trim() : '',
    media_id: mediaId ? String(mediaId).trim() : '',
    raw_payload: body,
    session_id: 'feishu:' + String(chatId) + ':' + String(senderId)
  };
}

return $input.all().map((item) => ({ json: normalize(item.json) }));

function parseMaybeJson(value) {
  if (typeof value !== 'string') return value || {};
  try {
    return JSON.parse(value);
  } catch (error) {
    return { query: value };
  }
}

function first(...values) {
  return values.find((value) => value !== undefined && value !== null && String(value).trim() !== '');
}

function extractOrderId(input) {
  const text = String(first(input.order_id, input.orderId, input.input, input.query, input.text, '')).trim();
  const match = text.match(/\bord_[0-9A-Za-z]+\b/i);
  return match ? match[0].toLowerCase() : '';
}

try {
  const input = parseMaybeJson(query);
  const orderId = extractOrderId(input);
  if (!orderId) {
    return JSON.stringify({ ok: false, error: 'missing_order_id', message: '请提供订单号，例如 ord_100。' });
  }

  const orderUrl = 'http://mock-api:8000/orders/' + encodeURIComponent(orderId);
  const order = await helpers.httpRequest({
    method: 'GET',
    url: orderUrl,
    json: true
  });
  if (!order.shipment_id) {
    return JSON.stringify({ ok: false, error: 'missing_shipment_id', step: 'parse_order', order_id: orderId, order });
  }

  const shipmentUrl = 'http://mock-api:8000/shipments/' + encodeURIComponent(order.shipment_id);
  const shipment = await helpers.httpRequest({
    method: 'GET',
    url: shipmentUrl,
    json: true
  });

  const suggestion = Number(shipment.delay_days || 0) > 0 || shipment.status === 'delayed'
    ? '建议客服主动安抚客户，并跟进物流延迟原因。'
    : '建议告知客户订单状态正常，无需人工介入。';
  return [
    '查询成功。',
    '订单号：' + order.order_id,
    '订单状态：' + order.status,
    '订单金额：' + order.value,
    '物流商：' + shipment.carrier,
    '物流状态：' + shipment.status,
    '延迟天数：' + shipment.delay_days,
    '行动建议：' + suggestion
  ].join('\n');
} catch (error) {
  return JSON.stringify({
    ok: false,
    error: 'tool_runtime_error',
    step: 'unexpected_exception',
    message: error && error.message ? error.message : String(error)
  });
}

